  /// Jellyfin API key (with `username` naming whose state to read), or a
  /// ListenBrainz user token.
  final String? token;

  /// A staged account export to read, from `stageMigrationExport`. Required for
  /// `spotify` and refused for every source that reads a server.
  final String? exportId;

  final MigrationOptions? options;

  /// Match and report without writing anything.
  final bool dryRun;
}

/// One uploaded account data export, staged for an import to read.
class MigrationExport {
  const MigrationExport({
    required this.pid,
    required this.source,
    required this.files,
    required this.sizeBytes,
    required this.expiresAt,
  });

  /// Goes on `createMigration` as `exportId`.
  final String pid;

  /// Which service's export this was recognised as. `unknown` is reserved for a
  /// server that stages an archive without naming it; this one refuses what it
  /// cannot read, so nothing it stages carries that value.
  final String source;

  /// The files inside the archive this import will read.
  final List<String> files;

  /// The uploaded archive's size on disk.
  final int sizeBytes;

  /// When the staged file is swept. An import that has not started by then has
  /// to upload the export again.
  final DateTime expiresAt;
}

/// What to import. Everything defaults to true.
class MigrationOptions {
  const MigrationOptions({
    this.stars = true,
    this.ratings = true,
    this.history = true,
    this.progress = true,
  });

  /// Starred songs, albums, and artists.
  final bool stars;

  /// Song and album ratings.
  final bool ratings;

  /// Play counts, as backdated import-source listen sessions with deterministic
  /// ids (re-runs never double-count).
  final bool history;

  /// In-progress positions (Subsonic bookmarks, Audiobookshelf media progress)
  /// onto matched items' resume state.
  final bool progress;
}

/// What kind of scan to run.
class RescanOptions {
  const RescanOptions({this.force = false});

  /// Re-read every file even when its size and mtime are unchanged, re-hashing
  /// and re-parsing tags - the repair pass for rows written before a parser
  /// fix, priced at a full library read. Curated fields stay preserved: a
  /// forced scan never overrides locked edits.
  final bool force;
}

/// A staged restore: what will happen at the next server start.
class RestorePlan {
  const RestorePlan({
    required this.backupId,
    required this.stagedAt,
    required this.keyfilePresent,
    required this.keyfileMatches,
    this.sealedCasualties = const [],
    this.warnings = const [],
  });

  /// The backup the restore applies.
  final String backupId;

  /// When the restore was staged.
  final DateTime stagedAt;

  /// Whether this server holds an encryption key.
  final bool keyfilePresent;

  /// Whether this server's key opens the archive's sealed credentials. False
  /// means every entry in `sealedCasualties` becomes unusable after restore and
  /// is marked pending re-auth instead of surfacing as scattered errors.
  final bool keyfileMatches;

  /// The credentials that break when the key does not match; empty when it
  /// does.
  final List<SealedCasualty> sealedCasualties;

  /// Human-readable cautions (schema differences, a server-version gap, an
  /// archive older than the current data).
  final List<String> warnings;
}

/// One scheduled job's configuration and history.
class Schedule {
  const Schedule({
    required this.kind,
    required this.cron,
    required this.enabled,
    this.lastRunAt,
    this.lastStatus,
    this.lastError,
    this.nextRunAt,
  });

  final String kind;

  /// Five-field cron expression (minute, hour, day of month, month, day of
  /// week), server-local time.
  final String cron;

  /// Whether the schedule fires.
  final bool enabled;

  /// When the job last ran; absent if never.
  final DateTime? lastRunAt;

  /// `ok` or `failed` for the last run. An open string.
  final String? lastStatus;

  /// Failure detail when the last run failed.
  final String? lastError;

  /// The next firing time while enabled.
  final DateTime? nextRunAt;
}

/// Every schedule.
class ScheduleList {
  const ScheduleList({required this.schedules});

  /// One entry per kind.
  final List<Schedule> schedules;
}

/// A schedule change.
class SchedulePut {
  const SchedulePut({required this.cron, required this.enabled});

  /// Five-field cron expression.
  final String cron;

  /// Whether the schedule fires.
  final bool enabled;
}

/// The server-level scrobbling credential state.
class ScrobblingAdminConfig {
  const ScrobblingAdminConfig({
    required this.lastfmConfigured,
    required this.lastfmSource,
    required this.lastfmSecretSet,
    this.lastfmApiKey,
  });

  /// Whether a usable Last.fm API credential pair is in effect (users can link
  /// accounts and the connect button enables).
  final bool lastfmConfigured;

  /// Where the effective pair came from: `settings`, `environment`, or `none`.
  /// An open string.
  final String lastfmSource;

  /// The effective API key, for display in the admin form. Present only when
  /// configured; the shared secret is never returned.
  final String? lastfmApiKey;

  /// Whether a shared secret is stored.
  final bool lastfmSecretSet;
}

/// A Last.fm API credential change: both values to set, both empty to clear
/// back to environment credentials.
class ScrobblingAdminConfigPut {
  const ScrobblingAdminConfigPut({
    required this.lastfmApiKey,
    required this.lastfmSecret,
  });

  /// The Last.fm API key.
  final String lastfmApiKey;

  /// The Last.fm shared secret.
  final String lastfmSecret;
}

/// One credential a key-mismatched restore breaks.
class SealedCasualty {
  const SealedCasualty({required this.kind, required this.name});

  /// What kind of credential: `app-password`, `private-feed`,
  /// `scrobble-connection`, or others as integrations grow. An open string.
  final String kind;

  /// Which one, in user terms ("Symfonium on the kitchen tablet", the feed's
  /// show title).
  final String name;
}

/// What the generated thumbnail cache holds, and what the source images behind
/// it cost.
class ThumbnailCacheReport {
  const ThumbnailCacheReport({
    required this.rows,
    required this.bytes,
    required this.sources,
    required this.artSources,
    required this.artSourceBytes,
    required this.rungs,
    this.oldestAt,
    this.newestAt,
  });

  /// Cached thumbnails held.
  final int rows;

  /// What those thumbnails cost.
  final int bytes;

  /// Source images with at least one derivative, out of `artSources`.
  final int sources;

  /// Source images held.
  final int artSources;

  /// What those originals cost. The figure `bytes` is read against: a cache
  /// smaller than its own sources is doing its job.
  final int artSourceBytes;

  /// When the oldest cached thumbnail was generated. Absent when the cache is
  /// empty.
  final DateTime? oldestAt;

  /// When the newest cached thumbnail was generated. Absent when the cache is
  /// empty.
  final DateTime? newestAt;

  /// Per-rung breakdown, largest box first.
  final List<ThumbnailRung> rungs;
}

/// Which cached thumbnails to drop. Both bounds are optional and an absent one
/// leaves that axis unbounded, but at least one must be given - a request with
/// neither is refused rather than read as "everything". Zero is a value, not an
/// absence: `olderThanSeconds: 0` drops every entry, and `maxBytes: 0` evicts
/// the cache entirely.
class ThumbnailPruneRequest {
  const ThumbnailPruneRequest({this.olderThanSeconds, this.maxBytes});

  /// Drop entries generated at least this long ago. Absent leaves the age
  /// unbounded.
  final int? olderThanSeconds;

  /// Evict oldest-first until the cache fits this many bytes. Absent leaves the
  /// size unbounded.
  final int? maxBytes;
}

/// What a thumbnail-cache prune dropped.
class ThumbnailPruneResult {
  const ThumbnailPruneResult({required this.removed, required this.freedBytes});

  /// Cached thumbnails dropped.
  final int removed;

  /// What they held. Freed inside the catalog file rather than returned to the
  /// filesystem.
  final int freedBytes;
}

/// One ladder rung's share of the thumbnail cache.
class ThumbnailRung {
  const ThumbnailRung({
    required this.size,
    required this.rows,
    required this.bytes,
  });

  /// The rung in pixels. A requested box is rounded up to one of these, which
  /// is what bounds how many derivatives a single cover can accumulate.
  final int size;

  /// Cached thumbnails at this rung.
  final int rows;

  /// What they cost.
  final int bytes;
}

/// One background tool task.
class ToolTask {
  const ToolTask({
    required this.id,
    required this.type,
    required this.state,
    required this.createdAt,
    this.itemPid,
    this.itemTitle,
    this.progressPct,
    this.error,
    this.waitReason,
    this.retryAt,
    this.bookInTrash = false,
    this.resultPids = const [],
    this.finishedAt,
    this.summary,
  });

  /// Task pid.
  final String id;

  /// The operation: `book-merge`, `book-split`, `cue-split`, `acquire`,
  /// `playlist-sync`, `genre-normalize`, `health-fix`, `catalog-repair`, or an
  /// `import-` migration (`import-jellyfin`, `import-subsonic`, ...). A string,
  /// not a closed enum.
  final String type;

  /// `queued`, `running`, `done`, `failed`, or `parked`: a book merge or split,
  /// or a CUE split, whose runs kept ending with the server. Parked is terminal
  /// and counts as failed: the task is not run again, the delete, Clear
  /// finished and the retention prune take it as they take a failed task, and
  /// until one does it keeps the book or rip it works on from another merge or
  /// split. A string, not a closed enum.
  final String state;

  /// The book, track, or playlist the task was started from.
  final String? itemPid;

  /// What `itemPid` was called when the task was queued: a book merge's or
  /// split's book, a CUE split's album. Absent for other tasks.
  final String? itemTitle;

  /// Progress in percent when the engine reports it.
  final double? progressPct;

  /// Why the task failed, when `failed`, or stopped, when `parked`, where it
  /// also says where each file the run made or moved is (new files waiting
  /// beside the book, originals in the trash) and what clearing the task does
  /// with new files still hidden. While a book merge or split, a CUE split, or
  /// a catalog repair is `running` it can say what the task waits out instead,
  /// in the server's words beside `waitReason`.
  final String? error;

  /// Set while a `running` book merge or split, or CUE split, waits to try
  /// again on its own, at `retryAt`: `catalog-busy` (another job holds the
  /// catalog), `catalog-maintenance`, `read-only` (a library it works in is
  /// flagged read-only), `storage-unwritable` (a folder refuses the server),
  /// `engine-unavailable`, `part-missing` (a file the catalog has is not where
  /// it says), `put-back-blocked` (a file going back from the trash cannot),
  /// `stopped` (the server stopped or the run ran out of time), or `other`. A
  /// `catalog-repair` that a catalog hand-off cut short waits too, with
  /// `catalog-maintenance`, and starts over once the catalog is back. A book
  /// merge or split, or CUE split, waits at most six hours in a row, then ends
  /// safely for how far it went. A string, not a closed enum.
  final String? waitReason;

  /// When a waiting task tries again.
  final DateTime? retryAt;

  /// True while a book merge's or split's sources are in the trash and its new
  /// files not yet the book: the book is missing from the library until the
  /// task finishes.
  final bool bookInTrash;

  /// What the task produced once `done`: the merged book or the split pieces
  /// (item pids), or the review entries an acquisition or playlist sync opened
  /// (entry pids).
  final List<String> resultPids;

  /// When the task was queued.
  final DateTime createdAt;

  /// When it reached a terminal state.
  final DateTime? finishedAt;

  /// Task-type-specific result detail once the task finishes, for example a
  /// migration import's match-and-write report. Shapes are documented per task
  /// type and may grow fields. A `health-fix` task carries `rule` from the
  /// moment it is queued, and once it has run `attempted`, `filled`, `failed`
  /// (item counts) and `skipped`, an object counting the items left alone by
  /// reason (`gone`, `locked`, `no match`, ...); a `path-mismatch` fix also
  /// carries `moved` (the items it moved), `held` (by hold code) and `jobPids`
  /// (the organize jobs that moved them). A `catalog-repair` task carries each
  /// step's count once that step has run, added up over its attempts and absent
  /// for a step none has reached: `sortKeysRewritten`, `orphansDeleted`
  /// (entities with no items deleted), `orphansPending` (those its last orphans
  /// step noted for the next repair), `artSourcesReclaimed`,
  /// `thumbnailsReclaimed`, `tagProvenanceReclaimed`,
  /// `strandedTagRowsReclaimed` and `searchRowsRebuilt` (entries written or
  /// dropped); `runs`, what each run of the task did: the steps it finished, in
  /// order, with `error` saying why a run stopped short and `handedOff` marking
  /// one a catalog hand-off cut short; and once it has run, `after`, the
  /// `CatalogConsistency` its closing check read.
  final Map<String, Object?>? summary;
}

/// What the transcoder is doing right now, for context beside the limits.
class TranscodingActivity {
  const TranscodingActivity({
    required this.activeSessions,
    this.activeTimelines,
  });

  /// Engine-backed sessions in flight: what the concurrent caps are counting.
  /// Both a floor and a ceiling on what is "really" being transcoded - a client
  /// that forced the source's own format is routed through the engine and
  /// counted here though nothing is re-encoded.
  final int activeSessions;

  /// How much of `activeSessions` is listeners playing a queue as one gapless
  /// rendering. One slot a listener, however many timelines they hold live at
  /// once, released when every one of them has gone unfetched for a minute.
  /// Absent from a server that does not separate them.
  final int? activeTimelines;
}

/// Transcode session limits, enforced at the media proxy when a stream engages
/// the streaming engine (direct-played originals never count).
class TranscodingLimits {
  const TranscodingLimits({
    required this.maxConcurrent,
    required this.maxConcurrentPerUser,
    required this.defaultMaxBitrateKbps,
  });

  /// Server-wide concurrent transcode session cap; 0 is unlimited (the
  /// streaming engine's own admission control remains the backstop).
  final int maxConcurrent;

  /// Per-account concurrent transcode session cap; 0 is unlimited.
  /// Administrators are exempt.
  final int maxConcurrentPerUser;

  /// Default transcode bitrate ceiling in kbit/s for accounts without their own
  /// `maxTranscodeKbps`; 0 is unlimited.
  final int defaultMaxBitrateKbps;
}

/// What an empty-trash pass did.
class TrashEmptyResult {
  const TrashEmptyResult({
    required this.purged,
    required this.errored,
    required this.reclaimedBytes,
    this.skippedReadOnly = 0,
  });

  /// Files permanently deleted.
  final int purged;

  /// Files that could not be purged (retry later).
  final int errored;

  /// Disk space reclaimed.
  final int reclaimedBytes;

  /// Entries left in the trash because their library is read-only.
  final int skippedReadOnly;
}

/// One file in the catalog's deletion undo journal.
class TrashEntry {
  const TrashEntry({
    required this.id,
    required this.name,
    required this.reason,
    required this.sizeBytes,
    required this.trashedAt,
    this.itemPid,
    this.restoredAt,
    this.libraryPid,
    this.libraryName,
  });

  /// Trash entry PID.
  final String id;

  /// The item the file belonged to.
  final String? itemPid;

  /// The file's original library-relative path.
  final String name;

  /// Why it was deleted: `user`, `prune` or `permanent`, or the file tool whose
  /// run took it (`book-merge`, `book-split`, `cue-split`). An open string.
  final String reason;

  /// File size.
  final int sizeBytes;

  /// When it was deleted.
  final DateTime trashedAt;

  /// When it was restored; absent while trashed.
  final DateTime? restoredAt;

  /// The library the file was trashed from, when the journal names one.
  final String? libraryPid;

  /// That library's name, when it still has one.
  final String? libraryName;
}

/// The trash journal.
class TrashList {
  const TrashList({required this.entries});

  /// Entries, newest first.
  final List<TrashEntry> entries;
}

/// What purging one trash entry reclaimed.
class TrashPurgeResult {
  const TrashPurgeResult({required this.reclaimedBytes});

  /// Disk space reclaimed by purging the entry.
  final int reclaimedBytes;
}
